//! Phase 3 (Issue 3) golden-fixture harness: robust ML optimiser on short
//! records (the hail-region data shape).
//!
//! Loads `tests/golden/short_record_golden.json` (generated by
//! `tools/generate_short_record_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and checks that the Rust [`fit`] reaches the same
//! optimum as the reference on short (n = 10-15) hail-region-shaped records.
//!
//! # What is compared
//!
//! - **Log-likelihood** (`loglik`): the Rust `fit` log-likelihood vs. the
//!   reference `optim` log-likelihood. This is the objective, which is
//!   well-determined at the optimum, so it is compared at the §7.2 tolerance.
//! - **`ml_params`**: the Rust fitted parameters vs. the reference, at the
//!   optimizer tolerance (§3.2).
//! - **No NaN**: every fitted parameter and every CP quantile must be finite.
//!
//! # The defect (Issue 3)
//!
//! The hand-rolled BFGS lacks the reference's robust multi-start / init
//! strategy, so on short records it stopped at a worse fit (return levels
//! changed in 19-39% of hail regions; NaN in up to 121 regions). The Rust
//! [`fit_with_config`] now seeds from `setics`-style heuristics in addition to
//! the caller's `init`, adds a Nelder-Mead polish, and keeps the best
//! log-likelihood.
//!
//! # Tolerance policy (§7.2)
//!
//! The consolidated, canonical tolerance policy lives in
//! [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md); the summary
//! below is the subset relevant to this harness.
//!
//! The log-likelihood is compared at the §7.2 tolerance (`rtol = 1e-8`); the
//! optimizer-produced `ml_params` use `rtol = 1e-4` (§3.2).

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::mle::fit;
use fitdistcp_core::models::GenExtreme;

/// §7.2 golden tolerance for the log-likelihood (the objective).
const RTOL: f64 = 1e-8;
const ATOL: f64 = 1e-10;

/// Tolerance for the optimizer-produced `ml_params` (§3.2).
const OPT_RTOL: f64 = 1e-4;
const OPT_ATOL: f64 = 1e-6;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.bytes[self.pos + 1..self.pos + 5])
                                .expect("utf8 hex");
                            let code = u32::from_str_radix(hex, 16).expect("hex");
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            self.pos += 4;
                        }
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "short_record_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

/// The short-record datasets and their reference model keys.
const CASES: [(&str, &str); 3] = [
    ("hail_region_a", "hail_region_a"),
    ("hail_region_b", "hail_region_b"),
    ("hail_region_c", "hail_region_c"),
];

/// The Rust fit's log-likelihood matches the reference on every short record,
/// and no region returns NaN (Issue 3, Phase 3).
#[test]
fn golden_short_record_loglik_matches_reference() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");

    for (name, ds_key) in CASES {
        let y = datasets.get(ds_key).as_f64_vec();
        assert!(
            (10..=15).contains(&y.len()),
            "{name}: fixture must be a short record (n = 10-15), got n = {}",
            y.len()
        );
        let m = models.get(name);
        let ref_params = m.get("params").as_f64_vec();
        let ref_loglik = m.get("loglik").as_f64();

        // The Rust fit uses the caller's init; the multi-start adds the
        // `setics` heuristic internally. A generic init is fine here.
        let r = fit(&GenExtreme, &y, &[1.4, 0.3, -0.1]);

        // (1) No NaN: every fitted parameter is finite.
        assert!(
            r.ml_params.iter().all(|v| v.is_finite()),
            "{name}: ml_params not finite: {:?}",
            r.ml_params
        );
        assert!(
            r.loglik.is_finite(),
            "{name}: loglik not finite: {}",
            r.loglik
        );

        // (2) The log-likelihood matches the reference at the §7.2 tolerance.
        assert_close(r.loglik, ref_loglik, RTOL, ATOL, &format!("{name}.loglik"));

        // (3) The fitted parameters match the reference (optimizer tolerance).
        compare_vec(
            &r.ml_params,
            &ref_params,
            OPT_RTOL,
            OPT_ATOL,
            &format!("{name}.ml_params"),
        );

        // (4) The chosen start is reported for diagnostics and is finite.
        assert!(
            r.start.iter().all(|v| v.is_finite()),
            "{name}: chosen start not finite: {:?}",
            r.start
        );

        eprintln!(
            "{name}: n = {}, loglik = {:.10}, ref = {:.10}, params = {:?}, start = {:?}",
            y.len(),
            r.loglik,
            ref_loglik,
            r.ml_params,
            r.start
        );
    }
}

/// The multi-start strategy rescues a deliberately bad single start: the Rust
/// fit from a poor init still reaches the reference log-likelihood (Issue 3).
///
/// This pins the fix: before Phase 3 the hand-rolled BFGS could stop at a worse
/// fit from a poor init; the multi-start now adds the `setics`-style start and
/// keeps the best log-likelihood, so the result is init-independent.
#[test]
fn golden_short_record_multistart_is_init_independent() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");

    for (name, ds_key) in CASES {
        let y = datasets.get(ds_key).as_f64_vec();
        let m = models.get(name);
        let ref_loglik = m.get("loglik").as_f64();

        // A deliberately poor init: a large scale and a positive shape, far
        // from the negative-shape optimum.
        let poor = fit(&GenExtreme, &y, &[5.0, 5.0, 0.5]);
        assert!(
            poor.ml_params.iter().all(|v| v.is_finite()),
            "{name}: poor-init fit not finite: {:?}",
            poor.ml_params
        );
        assert_close(
            poor.loglik,
            ref_loglik,
            RTOL,
            ATOL,
            &format!("{name}.poor_init.loglik"),
        );

        // A good init reaches the same optimum.
        let good = fit(&GenExtreme, &y, &[1.4, 0.3, -0.1]);
        assert_close(
            good.loglik,
            ref_loglik,
            RTOL,
            ATOL,
            &format!("{name}.good_init.loglik"),
        );

        // The two inits agree (the multi-start makes the fit init-independent).
        assert_close(
            poor.loglik,
            good.loglik,
            RTOL,
            ATOL,
            &format!("{name}.init_independence"),
        );
    }
}
